import json,urllib.request,urllib.error,urllib.parse

def deliver(url,payload,max_attempts=3):
    parsed=urllib.parse.urlsplit(url)
    if parsed.scheme!='http' or parsed.hostname!='127.0.0.1' or not parsed.port or parsed.path!='/notify' or parsed.query or parsed.fragment:raise ValueError('loopback fixture endpoint required')
    if isinstance(max_attempts,bool) or not isinstance(max_attempts,int) or not 1<=max_attempts<=5:raise ValueError('invalid attempt limit')
    body=json.dumps(payload,ensure_ascii=False,sort_keys=True).encode('utf8')
    key=str(payload.get('notification_id',''))
    if not key:raise ValueError('notification_id required')
    opener=urllib.request.build_opener(urllib.request.ProxyHandler({}))
    for attempt in range(1,max_attempts+1):
        req=urllib.request.Request(url,data=body,headers={'Content-Type':'application/json','Idempotency-Key':key},method='POST')
        try:
            with opener.open(req,timeout=1) as response:
                status=response.status;raw=response.read(4096)
        except urllib.error.HTTPError as exc:
            status=exc.code;raw=exc.read(4096)
        except (OSError,TimeoutError):
            status=503;raw=b''
        try:result=json.loads(raw) if raw else {}
        except (ValueError,UnicodeDecodeError):result={}
        if 200<=status<300:
            if result.get('accepted') is True:return {'ok':True,'attempts':attempt}
            return {'ok':False,'kind':'business_rejected','attempts':attempt}
        if status==429 or 500<=status<600:
            if attempt<max_attempts:continue
            return {'ok':False,'kind':'transient_exhausted','attempts':attempt}
        return {'ok':False,'kind':'permanent_rejected','attempts':attempt}
